def _fingerprint(value):
    return hashlib.sha256(
        json.dumps(
            value, sort_keys=True, ensure_ascii=False, separators=(",", ":"),
        ).encode()
    ).hexdigest()


def _version(Model, *, document_id, parent_id, origin, ancestry, content_digest,
             evidence, created_at, source_snapshot_id=None):
    return Model.objects.create(
        document_id=document_id,
        parent_id=parent_id,
        source_snapshot_id=source_snapshot_id,
        origin=origin,
        ancestry=ancestry,
        content_digest=content_digest,
        evidence=evidence,
        evidence_digest=_fingerprint(evidence),
        created_at=created_at,
    )


def preserve_reader_targets(apps, schema_editor):
    Document = apps.get_model("library", "Document")
    Rendition = apps.get_model("library", "Rendition")
    ContentOrganization = apps.get_model("library", "ContentOrganization")
    DocumentPublication = apps.get_model("library", "DocumentPublication")
    from importlib import import_module

    profile_key = import_module(settings.READING_HUB_PROFILE).PROFILE.key
    for document in Document.objects.all().iterator():
        organization = (
            ContentOrganization.objects.filter(
                entry__url=document.url, entry__site__profile=profile_key,
            ).select_related("rendition").first()
        )
        rendition = (
            organization.rendition if organization else
            Rendition.objects.filter(document_id=document.pk)
            .order_by("-created_at", "-pk").first()
        )
        if rendition:
            Document.objects.filter(pk=document.pk).update(
                reader_rendition_id=rendition.pk,
                reader_selection_explicit=DocumentPublication.objects.filter(
                    rendition_id=rendition.pk,
                ).exists(),
            )


